import type { Metadata } from 'next'

import { mergeOpenGraph } from '@/utilities/mergeOpenGraph'
import { Order } from '@/payload-types'
import { getPayload } from 'payload'
import { redirect } from 'next/navigation'
import { AddressListing } from '@/components/addresses/AddressListing'
import { CreateAddressModal } from '@/components/addresses/CreateAddressModal'
import { SurfaceCard } from '@/components/ui/surface-card'
import { getCustomerAuthUser } from '@/utilities/getCustomerAuthUser'
import configPromise from '@payload-config'
import { headers as getHeaders } from 'next/headers.js'

export default async function AddressesPage() {
  const headers = await getHeaders()
  const user = await getCustomerAuthUser(headers)
  if (!user) {
    redirect(
      `/login?warning=${encodeURIComponent('Please login to access your account settings.')}`,
    )
  }

  const payload = await getPayload({ config: configPromise })

  let orders: Order[] | null = null

  try {
    const ordersResult = await payload.find({
      collection: 'orders',
      limit: 5,
      user,
      overrideAccess: false,
      pagination: false,
      where: {
        customer: {
          equals: user?.id,
        },
      },
    })

    orders = ordersResult?.docs || []
  } catch (error) {
    // when deploying this template on Payload Cloud, this page needs to build before the APIs are live
    // so swallow the error here and simply render the page with fallback data where necessary
    // in production you may want to redirect to a 404  page or at least log the error somewhere
    // console.error(error)
  }

  return (
    <>
      <SurfaceCard className="gap-6 rounded-lg border-0 p-8 shadow-sm shadow-black/10 dark:shadow-black/40">
        <h1 className="text-3xl font-medium mb-8">Addresses</h1>

        <div className="mb-8">
          <AddressListing />
        </div>

        <CreateAddressModal />
      </SurfaceCard>
    </>
  )
}

export const metadata: Metadata = {
  description: 'Manage your addresses.',
  openGraph: mergeOpenGraph({
    title: 'Addresses',
    url: '/account/addresses',
  }),
  title: 'Addresses',
}

import type { Booking, Service } from '@/payload-types'
import type { Metadata } from 'next'

import { Price } from '@/components/Price'
import { Button } from '@/components/ui/button'
import { formatDateDisplayDMY, toDateOnlyString } from '@/utilities/dateOnly'
import { formatDateTime } from '@/utilities/formatDateTime'
import { mergeOpenGraph } from '@/utilities/mergeOpenGraph'
import Link from 'next/link'
import { notFound } from 'next/navigation'
import { headers as getHeaders } from 'next/headers.js'
import configPromise from '@payload-config'
import { getPayload } from 'payload'
import { getSiteConfig } from '@/config/site'
import { AccountDetailMetaLabel, AccountDetailPanel } from '@/components/account/AccountDetailPanel'
import { getCustomerAuthUser } from '@/utilities/getCustomerAuthUser'

export const dynamic = 'force-dynamic'

type PageProps = {
  params: Promise<{ id: string }>
  searchParams: Promise<{ email?: string; accessToken?: string }>
}

export default async function BookingInvoicePage({ params, searchParams }: PageProps) {
  const headers = await getHeaders()
  const payload = await getPayload({ config: configPromise })
  const user = await getCustomerAuthUser(headers)
  const { enableInvoices } = getSiteConfig()

  const { id } = await params
  const { email = '', accessToken = '' } = await searchParams

  let booking: Booking | null = null

  try {
    const {
      docs: [bookingResult],
    } = await payload.find({
      collection: 'bookings',
      user,
      overrideAccess: !Boolean(user),
      depth: 1,
      where: {
        and: [
          { id: { equals: id } },
          ...(user
            ? [{ customer: { equals: user.id } }]
            : [
                { accessToken: { equals: accessToken } },
                ...(email
                  ? [
                      {
                        guestEmail: {
                          equals: email,
                        },
                      },
                    ]
                  : []),
              ]),
        ],
      },
      select: {
        id: true,
        service: true,
        guestEmail: true,
        guestName: true,
        slotDate: true,
        slotTime: true,
        status: true,
        amount: true,
        currency: true,
        stripePaymentIntentId: true,
        createdAt: true,
        customer: true,
        accessToken: true,
      },
    })

    const canAccessAsGuest =
      !user &&
      email &&
      accessToken &&
      bookingResult &&
      bookingResult.guestEmail &&
      bookingResult.guestEmail === email
    const canAccessAsUser =
      user &&
      bookingResult &&
      bookingResult.customer &&
      (typeof bookingResult.customer === 'object'
        ? bookingResult.customer.id
        : bookingResult.customer) === user.id

    if (bookingResult && (canAccessAsGuest || canAccessAsUser)) {
      booking = bookingResult as Booking
    }
  } catch (error) {
    console.error(error)
  }

  if (!booking) {
    notFound()
  }

  const service =
    booking.service && typeof booking.service === 'object' ? (booking.service as Service) : null

  const invoicePdfHref =
    enableInvoices && booking.amount != null && booking.amount > 0
      ? user
        ? `/api/invoices/bookings/${booking.id}`
        : accessToken && email
          ? `/api/invoices/bookings/${booking.id}?accessToken=${encodeURIComponent(accessToken)}&email=${encodeURIComponent(email)}`
          : null
      : null

  return (
    <AccountDetailPanel
      backHref={user ? '/account/bookings' : undefined}
      backLabel={user ? 'My bookings' : undefined}
      badgeLabel={`Booking #${booking.id}`}
    >
        <div className="flex flex-col gap-6 lg:flex-row lg:justify-between">
          <div>
            <AccountDetailMetaLabel>Booked on</AccountDetailMetaLabel>
            <p className="text-lg">
              <time dateTime={booking.createdAt}>
                {formatDateTime({ date: booking.createdAt })}
              </time>
            </p>
          </div>

          <div>
            <AccountDetailMetaLabel>Appointment</AccountDetailMetaLabel>
            <p className="text-lg">
              <time dateTime={toDateOnlyString(booking.slotDate)}>
                {formatDateDisplayDMY(booking.slotDate)}
              </time>{' '}
              at {booking.slotTime}
            </p>
          </div>

          {booking.amount != null && booking.amount > 0 ? (
            <div>
              <AccountDetailMetaLabel>Total paid</AccountDetailMetaLabel>
              <Price className="text-lg" amount={booking.amount} />
            </div>
          ) : (
            <div>
              <AccountDetailMetaLabel>Payment</AccountDetailMetaLabel>
              <p className="text-lg text-muted-foreground">No charge</p>
            </div>
          )}
        </div>

        {invoicePdfHref ? (
          <div>
            <Button asChild variant="outline" className="w-fit">
              <a href={invoicePdfHref}>Download PDF invoice</a>
            </Button>
          </div>
        ) : null}

        {service && (
          <div>
            <h2 className="mb-2 font-mono text-sm uppercase text-muted-foreground">Service</h2>
            <p className="text-lg font-medium">{service.name}</p>
            {service.description ? (
              <p className="text-sm text-muted-foreground mt-1">{service.description}</p>
            ) : null}
          </div>
        )}

        <div className="flex flex-col sm:flex-row sm:gap-12 gap-4">
          <div>
            <AccountDetailMetaLabel>Status</AccountDetailMetaLabel>
            <p className="text-lg capitalize">{booking.status}</p>
          </div>
          {booking.stripePaymentIntentId ? (
            <div>
              <AccountDetailMetaLabel>Payment</AccountDetailMetaLabel>
              <p className="text-sm text-muted-foreground">Received via card</p>
            </div>
          ) : null}
        </div>
    </AccountDetailPanel>
  )
}

export async function generateMetadata({ params }: PageProps): Promise<Metadata> {
  const { id } = await params

  return {
    description: `Booking details for booking ${id}.`,
    openGraph: mergeOpenGraph({
      title: `Booking ${id}`,
      url: `/bookings/${id}`,
    }),
    title: `Booking ${id}`,
  }
}

import type { Order } from '@/payload-types'
import type { Metadata } from 'next'

import { Price } from '@/components/Price'
import { Button } from '@/components/ui/button'
import { formatDateTime } from '@/utilities/formatDateTime'
import { mergeOpenGraph } from '@/utilities/mergeOpenGraph'
import { getSiteConfig } from '@/config/site'
import Link from 'next/link'
import { notFound, redirect } from 'next/navigation'
import { ProductItem } from '@/components/ProductItem'
import { headers as getHeaders } from 'next/headers.js'
import configPromise from '@payload-config'
import { getPayload } from 'payload'
import { OrderStatus } from '@/components/OrderStatus'
import { AddressItem } from '@/components/addresses/AddressItem'
import { AccountDetailMetaLabel, AccountDetailPanel } from '@/components/account/AccountDetailPanel'
import { getCustomerAuthUser } from '@/utilities/getCustomerAuthUser'

export const dynamic = 'force-dynamic'

type PageProps = {
  params: Promise<{ id: string }>
  searchParams: Promise<{ email?: string; accessToken?: string }>
}

export default async function Order({ params, searchParams }: PageProps) {
  const { ecommerceEnabled, bookingEnabled, enableInvoices } = getSiteConfig()
  if (!ecommerceEnabled) {
    redirect(bookingEnabled ? '/account/bookings' : '/account')
  }

  const headers = await getHeaders()
  const payload = await getPayload({ config: configPromise })
  const user = await getCustomerAuthUser(headers)

  const { id } = await params
  const { email = '', accessToken = '' } = await searchParams

  let order: Order | null = null

  try {
    const {
      docs: [orderResult],
    } = await payload.find({
      collection: 'orders',
      user,
      overrideAccess: !Boolean(user),
      depth: 2,
      where: {
        and: [
          {
            id: {
              equals: id,
            },
          },
          ...(user
            ? [
                {
                  customer: {
                    equals: user.id,
                  },
                },
              ]
            : [
                {
                  accessToken: {
                    equals: accessToken,
                  },
                },
                ...(email
                  ? [
                      {
                        customerEmail: {
                          equals: email,
                        },
                      },
                    ]
                  : []),
              ]),
        ],
      },
      select: {
        amount: true,
        currency: true,
        items: true,
        customerEmail: true,
        customer: true,
        status: true,
        createdAt: true,
        updatedAt: true,
        shippingAddress: true,
      },
    })

    const canAccessAsGuest =
      !user &&
      email &&
      accessToken &&
      orderResult &&
      orderResult.customerEmail &&
      orderResult.customerEmail === email
    const canAccessAsUser =
      user &&
      orderResult &&
      orderResult.customer &&
      (typeof orderResult.customer === 'object'
        ? orderResult.customer.id
        : orderResult.customer) === user.id

    if (orderResult && (canAccessAsGuest || canAccessAsUser)) {
      order = orderResult
    }
  } catch (error) {
    console.error(error)
  }

  if (!order) {
    notFound()
  }

  const invoicePdfHref =
    enableInvoices && order.amount != null && order.amount > 0
      ? user
        ? `/api/invoices/${order.id}`
        : accessToken && email
          ? `/api/invoices/${order.id}?accessToken=${encodeURIComponent(accessToken)}&email=${encodeURIComponent(email)}`
          : null
      : null

  return (
    <AccountDetailPanel
      backHref={user ? '/orders' : undefined}
      backLabel={user ? 'All orders' : undefined}
      badgeLabel={`Order #${order.id}`}
    >
        <div className="flex flex-col gap-6 lg:flex-row lg:justify-between">
          <div className="">
            <AccountDetailMetaLabel>Order Date</AccountDetailMetaLabel>
            <p className="text-lg">
              <time dateTime={order.createdAt}>
                {formatDateTime({ date: order.createdAt })}
              </time>
            </p>
          </div>

          <div className="">
            <AccountDetailMetaLabel>Total</AccountDetailMetaLabel>
            {order.amount && <Price className="text-lg" amount={order.amount} />}
          </div>

          {order.status && (
            <div className="grow max-w-1/3">
              <AccountDetailMetaLabel>Status</AccountDetailMetaLabel>
              <OrderStatus className="text-sm" status={order.status} />
            </div>
          )}
        </div>

        {invoicePdfHref ? (
          <div>
            <Button asChild variant="outline" className="w-fit">
              <a href={invoicePdfHref}>Download PDF invoice</a>
            </Button>
          </div>
        ) : null}

        {order.items && (
          <div>
            <h2 className="mb-4 font-mono text-sm uppercase text-muted-foreground">Items</h2>
            <ul className="flex flex-col gap-6">
              {order.items?.map((item, index) => {
                if (typeof item.product === 'string') {
                  return null
                }

                if (!item.product || typeof item.product !== 'object') {
                  return <div key={index}>This item is no longer available.</div>
                }

                const variant =
                  item.variant && typeof item.variant === 'object' ? item.variant : undefined

                return (
                  <li key={item.id}>
                    <ProductItem
                      product={item.product}
                      quantity={item.quantity}
                      variant={variant}
                    />
                  </li>
                )
              })}
            </ul>
          </div>
        )}

        {order.shippingAddress && (
          <div>
            <h2 className="mb-4 font-mono text-sm uppercase text-muted-foreground">
              Shipping Address
            </h2>

            {/* @ts-expect-error - some kind of type hell */}
            <AddressItem address={order.shippingAddress} hideActions />
          </div>
        )}
    </AccountDetailPanel>
  )
}

export async function generateMetadata({ params }: PageProps): Promise<Metadata> {
  const { id } = await params

  return {
