      url: `/orders/${id}`,
    }),
    title: `Order ${id}`,
  }
}

import type { Order } from '@/payload-types'
import type { Metadata } from 'next'

import { mergeOpenGraph } from '@/utilities/mergeOpenGraph'
import { getSiteConfig } from '@/config/site'

import { OrderItem } from '@/components/OrderItem'
import { SurfaceCard } from '@/components/ui/surface-card'
import { headers as getHeaders } from 'next/headers'
import { getPayload } from 'payload'
import { redirect } from 'next/navigation'
import { getCustomerAuthUser } from '@/utilities/getCustomerAuthUser'
import configPromise from '@payload-config'

export default async function Orders() {
  const { ecommerceEnabled, bookingEnabled } = getSiteConfig()
  if (!ecommerceEnabled) {
    redirect(bookingEnabled ? '/account/bookings' : '/account')
  }

  const headers = await getHeaders()
  const user = await getCustomerAuthUser(headers)
  if (!user) {
    redirect(`/login?warning=${encodeURIComponent('Please login to access your orders.')}`)
  }

  const payload = await getPayload({ config: configPromise })

  let orders: Order[] | null = null

  try {
    const ordersResult = await payload.find({
      collection: 'orders',
      limit: 0,
      pagination: false,
      user,
      overrideAccess: false,
      where: {
        customer: {
          equals: user?.id,
        },
      },
    })

    orders = ordersResult?.docs || []
  } catch (error) {}

  return (
    <>
      <SurfaceCard className="w-full gap-6 rounded-lg border-0 p-8 shadow-sm shadow-black/10 dark:shadow-black/40">
        <h1 className="text-3xl font-medium mb-8">Orders</h1>
        {(!orders || !Array.isArray(orders) || orders?.length === 0) && (
          <p className="">You have no orders.</p>
        )}

        {orders && orders.length > 0 && (
          <ul className="flex flex-col gap-6">
            {orders?.map((order, index) => (
              <li key={order.id}>
                <OrderItem order={order} />
              </li>
            ))}
          </ul>
        )}
      </SurfaceCard>
    </>
  )
}

